        // 召回先提交：登记被拦截 422，无任何登记落库
        assertEquals(422, registration);
        assertEquals(0, sampleRows);
        assertEquals("OPEN", getPlan(planKey).path("status").asText());
    }
    assertEquals("RECALLED", batchStatus(parent));
}

